#include <bits/stdc++.h>
using namespace std;

struct Piece {
    int id;
    int k;
    vector<pair<int,int>> cells;
};

struct Orientation {
    vector<pair<int,int>> cells; // normalized to min 0,0
    int w, h; // bounding box
    int r, f;
};

vector<Orientation> getOrientations(const vector<pair<int,int>>& cells) {
    vector<Orientation> res;
    set<vector<pair<int,int>>> seen;
    for (int f = 0; f < 2; f++) {
        for (int r = 0; r < 4; r++) {
            vector<pair<int,int>> transformed;
            for (auto [x, y] : cells) {
                int tx = x, ty = y;
                if (f) tx = -tx; // reflect across y-axis
                for (int rr = 0; rr < r; rr++) {
                    int nx = ty, ny = -tx; // 90° clockwise
                    tx = nx; ty = ny;
                }
                transformed.push_back({tx, ty});
            }
            // normalize
            int minx = INT_MAX, miny = INT_MAX;
            for (auto [x, y] : transformed) { minx = min(minx, x); miny = min(miny, y); }
            for (auto& [x, y] : transformed) { x -= minx; y -= miny; }
            sort(transformed.begin(), transformed.end());
            if (seen.insert(transformed).second) {
                int maxx = 0, maxy = 0;
                for (auto [x, y] : transformed) { maxx = max(maxx, x); maxy = max(maxy, y); }
                res.push_back({transformed, maxx + 1, maxy + 1, r, f});
            }
        }
    }
    return res;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Piece> pieces(n);
    int totalCells = 0;
    for (int i = 0; i < n; i++) {
        pieces[i].id = i;
        cin >> pieces[i].k;
        pieces[i].cells.resize(pieces[i].k);
        for (int j = 0; j < pieces[i].k; j++) {
            cin >> pieces[i].cells[j].first >> pieces[i].cells[j].second;
        }
        totalCells += pieces[i].k;
    }

    // Precompute orientations for each piece
    vector<vector<Orientation>> allOrients(n);
    for (int i = 0; i < n; i++) {
        allOrients[i] = getOrientations(pieces[i].cells);
    }

    // Sort pieces by decreasing size, then by fewer orientations (more constrained first)
    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b){
        if (pieces[a].k != pieces[b].k) return pieces[a].k > pieces[b].k;
        return allOrients[a].size() < allOrients[b].size();
    });

    int bestArea = INT_MAX;
    int bestW = 0, bestH = 0;
    vector<int> bestX(n), bestY(n), bestR(n), bestF(n);

    // Try different widths
    int sqrtArea = (int)ceil(sqrt((double)totalCells));

    // Collect candidate widths
    vector<int> candidateW;
    for (int w = max(1, sqrtArea - 20); w <= sqrtArea + 200 && w <= totalCells; w++) {
        candidateW.push_back(w);
    }
    // Also try some wider rectangles
    for (int w = sqrtArea + 200; w <= min(totalCells, sqrtArea * 3); w += 10) {
        candidateW.push_back(w);
    }

    auto startTime = chrono::steady_clock::now();

    for (int W : candidateW) {
        auto now = chrono::steady_clock::now();
        if (chrono::duration_cast<chrono::milliseconds>(now - startTime).count() > 8000) break;

        int maxH = (totalCells + W - 1) / W + n * 10; // generous upper bound
        // Use a height profile (skyline) approach
        vector<int> height(W, 0); // height[x] = first free row in column x

        vector<int> px(n), py(n), pr(n), pf(n);
        bool valid = true;

        // Grid to check overlaps - use height profile based placement
        // For efficiency, use a set-based grid for large instances
        // Actually for up to 10000 pieces * 10 cells = 100000 cells, a grid is fine
        int H_alloc = maxH;
        if ((long long)W * H_alloc > 20000000LL) {
            H_alloc = 20000000 / W;
        }
        vector<vector<bool>> grid(W, vector<bool>(H_alloc, false));

        int currentMaxH = 0;

        for (int idx = 0; idx < n; idx++) {
            int i = order[idx];

            int bestPlaceScore = INT_MAX;
            int bx = -1, by = -1, br = -1, bf = -1;

            for (auto& ori : allOrients[i]) {
                if (ori.w > W) continue;

                // Try to place at lowest position using bottom-left
                for (int x = 0; x <= W - ori.w; x++) {
                    // Find minimum y where it fits starting from skyline
                    int minStartY = 0;
                    for (auto [cx, cy] : ori.cells) {
                        minStartY = max(minStartY, height[x + cx] - cy);
                    }
                    // But we need to also handle non-convex shapes
                    // Check from minStartY upward
                    int y = max(0, minStartY);
                    bool found = false;
                    for (int attempt = 0; attempt < 5; attempt++) {
                        if (y + ori.h > H_alloc) break;
                        bool ok = true;
                        for (auto [cx, cy] : ori.cells) {
                            if (grid[x + cx][y + cy]) { ok = false; y = y + 1; break; }
                        }
                        if (ok) { found = true; break; }
                    }
                    if (!found) {
                        // Linear search from minStartY
                        for (y = max(0, minStartY); y + ori.h <= H_alloc; y++) {
                            bool ok = true;
                            for (auto [cx, cy] : ori.cells) {
                                if (grid[x + cx][y + cy]) { ok = false; break; }
                            }
                            if (ok) { found = true; break; }
                        }
                    }
                    if (!found) continue;

                    int maxY = y + ori.h;
                    int score = max(currentMaxH, maxY) * 1000000 + y * 1000 + x;
                    if (score < bestPlaceScore) {
                        bestPlaceScore = score;
                        bx = x; by = y; br = ori.r; bf = ori.f;
                    }
                    if (y == 0) break; // Can't do better for this x direction
                }
            }

            if (bx < 0) { valid = false; break; }

            px[i] = bx; py[i] = by; pr[i] = br; pf[i] = bf;
            // Place cells
            auto& ori = *find_if(allOrients[i].begin(), allOrients[i].end(),
                [&](const Orientation& o){ return o.r == br && o.f == bf; });
            for (auto [cx, cy] : ori.cells) {
                grid[bx + cx][by + cy] = true;
                height[bx + cx] = max(height[bx + cx], by + cy + 1);
                currentMaxH = max(currentMaxH, by + cy + 1);
            }
        }

        if (!valid) continue;

        int H = currentMaxH;
        int area = W * H;
        if (area < bestArea || (area == bestArea && (H < bestH || (H == bestH && W < bestW)))) {
            bestArea = area;
            bestW = W; bestH = H;
            bestX = px; bestY = py; bestR = pr; bestF = pf;
        }
    }

    cout << bestW << " " << bestH << "\n";
    for (int i = 0; i < n; i++) {
        cout << bestX[i] << " " << bestY[i] << " " << bestR[i] << " " << bestF[i] << "\n";
    }
    return 0;
}
